/**
 * The contract `dialog.tsx` and `dialog.web.tsx` both implement. Separate
 * module for the usual reason: Metro resolves `./dialog` to `dialog.web.tsx`
 * on web, so the web file cannot import shared types from `./dialog` without
 * importing itself.
 *
 * Deliberately narrower than radix's own props: `open`/`onOpenChange` and the
 * section slots, which is the surface both platforms can actually honour. A
 * shared contract is also the only thing that makes the platform pair
 * checkable — TypeScript resolves the native file and never compares the two,
 * so `scripts/check-registry-build.mjs` compares the exported names instead.
 */
import type { ReactNode } from "react";

export type DialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  children: ReactNode;
};

/** Every part inside a `Dialog` — content, header, footer, title, description. */
export type DialogSectionProps = {
  className?: string | undefined;
  children?: ReactNode;
};

/**
 * The native dialog: a transparent `Modal` with a dimmed backdrop and a centred
 * card, matching what radix renders on web closely enough that no call site
 * needs to branch.
 *
 * What does not carry over from radix, and is not faked here: the focus trap
 * and the scroll lock (a `Modal` already owns the screen) and the enter/exit
 * animations beyond the `fade` the `Modal` does itself. `Escape` becomes
 * `onRequestClose`, which is the Android back button.
 *
 * `open === false` renders nothing at all, so a dialog's body unmounts between
 * openings exactly as it does on web.
 */

import { createContext, useContext } from "react";
import { Modal, Pressable, Text, View } from "react-native";
import type { DialogProps, DialogSectionProps } from "@/components/ui/dialog-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

/**
 * Radix wires its `Close` up through the `Root` it is nested in. There is no
 * equivalent on native, so `Dialog` publishes the closer and `DialogContent`
 * — which owns both the backdrop and the X — reads it.
 */
const DialogCloseContext = createContext<() => void>(() => {});

function Dialog({ open, onOpenChange, children }: DialogProps) {
  return (
    <Modal
      visible={open}
      transparent
      animationType="fade"
      onRequestClose={() => onOpenChange(false)}
    >
      <DialogCloseContext.Provider value={() => onOpenChange(false)}>
        {children}
      </DialogCloseContext.Provider>
    </Modal>
  );
}

function DialogContent({ className, children }: DialogSectionProps) {
  const close = useContext(DialogCloseContext);
  return (
    <View className="flex-1 items-center justify-center bg-black/80 p-6">
      {/* The backdrop is a sibling laid out underneath rather than a parent of
          the card, because `Pressable` has no `stopPropagation` — nesting the
          card inside it would make every press on the card close the dialog. */}
      <Pressable className="absolute inset-0" onPress={close} role="button" aria-label="Close" />
      <View
        className={cn(
          "w-full max-w-lg gap-4 rounded-lg border border-border bg-background p-6",
          className,
        )}
      >
        {children}
        <Pressable
          className="absolute right-4 top-4 opacity-70"
          onPress={close}
          // The `role` is hand-written because a `<button>` has no native counterpart.
          role="button"
          aria-label="Close"
        >
          <X className="h-4 w-4" />
        </Pressable>
      </View>
    </View>
  );
}

// `space-y-*` and `space-x-*` are child-combinator utilities nativewind does
// not implement; `gap` is the cross-platform equivalent and behaves the same
// for these two rows.
function DialogHeader({ className, children }: DialogSectionProps) {
  return <View className={cn("gap-1.5", className)}>{children}</View>;
}

function DialogFooter({ className, children }: DialogSectionProps) {
  return <View className={cn("flex-row justify-end gap-2", className)}>{children}</View>;
}

function DialogTitle({ className, children }: DialogSectionProps) {
  return (
    <Text
      // The `role` is hand-written because an `<h2>` has no native counterpart.
      role="heading"
      aria-level={2}
      className={cn("text-lg font-semibold leading-none tracking-tight text-foreground", className)}
    >
      {children}
    </Text>
  );
}

function DialogDescription({ className, children }: DialogSectionProps) {
  return <Text className={cn("text-sm text-muted-foreground", className)}>{children}</Text>;
}

export { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle };

/**
 * The web dialog: radix, unchanged in behaviour from before the split. It keeps
 * the focus trap, the scroll lock, the `Escape` handler and the enter/exit
 * animations, none of which have a native counterpart worth faking.
 *
 * The exported surface is `dialog-base.ts`'s, not radix's — see that file.
 */

import { Dialog as DialogPrimitive } from "radix-ui";
import type { DialogProps, DialogSectionProps } from "@/components/ui/dialog-base";
import { X } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

function Dialog({ open, onOpenChange, children }: DialogProps) {
  return (
    <DialogPrimitive.Root open={open} onOpenChange={onOpenChange}>
      {children}
    </DialogPrimitive.Root>
  );
}

function DialogContent({ className, children }: DialogSectionProps) {
  return (
    <DialogPrimitive.Portal>
      <DialogPrimitive.Overlay className="data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-black/80" />
      <DialogPrimitive.Content
        className={cn(
          "bg-background text-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border p-6 shadow-lg duration-200 sm:rounded-lg",
          className,
        )}
      >
        {children}
        <DialogPrimitive.Close className="ring-offset-background focus:ring-ring data-[state=open]:bg-accent data-[state=open]:text-muted-foreground absolute right-4 top-4 rounded-sm opacity-70 transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:pointer-events-none">
          <X className="h-4 w-4" />
          <span className="sr-only">Close</span>
        </DialogPrimitive.Close>
      </DialogPrimitive.Content>
    </DialogPrimitive.Portal>
  );
}

function DialogHeader({ className, children }: DialogSectionProps) {
  return (
    <div className={cn("flex flex-col gap-1.5 text-center sm:text-left", className)}>
      {children}
    </div>
  );
}

function DialogFooter({ className, children }: DialogSectionProps) {
  return (
    <div className={cn("flex flex-col-reverse sm:flex-row sm:justify-end sm:gap-2", className)}>
      {children}
    </div>
  );
}

function DialogTitle({ className, children }: DialogSectionProps) {
  return (
    <DialogPrimitive.Title
      className={cn("text-lg font-semibold leading-none tracking-tight", className)}
    >
      {children}
    </DialogPrimitive.Title>
  );
}

function DialogDescription({ className, children }: DialogSectionProps) {
  return (
    <DialogPrimitive.Description className={cn("text-muted-foreground text-sm", className)}>
      {children}
    </DialogPrimitive.Description>
  );
}

export { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle };
